(function(){const overlay=document.getElementById('pagePreviewOverlay');const content=document.getElementById('pagePreviewContent');const closeBtn=document.getElementById('pagePreviewClose');const title=document.getElementById('pagePreviewTitle');let activeGrid=null,activeDetails=null,lastTrigger=null;function closePreview(){if(!overlay.classList.contains('is-open'))return;if(activeGrid&&activeDetails)activeDetails.appendChild(activeGrid);activeGrid=null;activeDetails=null;content.replaceChildren();overlay.classList.remove('is-open');overlay.setAttribute('aria-hidden','true');document.body.classList.remove('preview-modal-open');if(lastTrigger)lastTrigger.focus();}document.querySelectorAll('.actualPages').forEach((details)=>{const trigger=details.querySelector('summary');const grid=details.querySelector('.actualPagesGrid');if(!trigger||!grid)return;trigger.setAttribute('role','button');trigger.setAttribute('aria-haspopup','dialog');trigger.addEventListener('click',(event)=>{event.preventDefault();event.stopPropagation();if(activeGrid)closePreview();activeGrid=grid;activeDetails=details;lastTrigger=trigger;const cardTitle=details.closest('.card')?.querySelector('.cardbody h3')?.innerText||'Actual Telugu eBook Pages';title.textContent=cardTitle+' — Actual Telugu Pages';content.appendChild(grid);overlay.classList.add('is-open');overlay.setAttribute('aria-hidden','false');document.body.classList.add('preview-modal-open');content.scrollTop=0;closeBtn.focus();});});closeBtn.addEventListener('click',closePreview);overlay.addEventListener('click',(event)=>{if(event.target===overlay)closePreview();});document.addEventListener('keydown',(event)=>{if(event.key==='Escape'&&overlay.classList.contains('is-open'))closePreview();});})();
(function(){const rail=document.getElementById('reviewRail');const prev=document.getElementById('reviewPrev');const next=document.getElementById('reviewNext');const pos=document.getElementById('reviewPosition');if(!rail||!prev||!next||!pos)return;const cards=Array.from(rail.querySelectorAll('.reviewCard'));if(!cards.length)return;let active=0;function render(){pos.textContent=(active+1)+' / '+cards.length;}function go(delta){active=Math.max(0,Math.min(cards.length-1,active+delta));render();cards[active].scrollIntoView({behavior:'smooth',block:'nearest',inline:'start'});}prev.addEventListener('click',()=>go(-1));next.addEventListener('click',()=>go(1));if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{let best=null;for(const entry of entries){if(entry.isIntersecting&&(!best||entry.intersectionRatio>best.intersectionRatio))best=entry;}if(best){active=cards.indexOf(best.target);render();}},{root:rail,threshold:[0.35,0.6,0.85]});cards.forEach(card=>observer.observe(card));}render();})();